import React, { useEffect, useMemo, useState } from "react";
import "./JsonPrettifier.css";

const SAMPLE_JSON = `{
  "name": "personal-blog",
  "tools": ["json prettifier", "validator", "minifier"],
  "settings": {
    "indent": 2,
    "sortKeys": false
  }
}`;

function sortObjectKeys(value) {
  if (Array.isArray(value)) {
    return value.map(sortObjectKeys);
  }

  if (value && typeof value === "object") {
    return Object.keys(value)
      .sort((a, b) => a.localeCompare(b))
      .reduce((sorted, key) => {
        sorted[key] = sortObjectKeys(value[key]);
        return sorted;
      }, {});
  }

  return value;
}

function countNodes(value) {
  if (Array.isArray(value)) {
    return value.reduce(
      (total, item) => total + countNodes(item),
      value.length
    );
  }

  if (value && typeof value === "object") {
    return Object.values(value).reduce(
      (total, item) => total + countNodes(item),
      Object.keys(value).length
    );
  }

  return 1;
}

function byteSize(value) {
  return new Blob([value]).size;
}

function JsonPrettifier() {
  const [input, setInput] = useState(SAMPLE_JSON);
  const [indent, setIndent] = useState(2);
  const [sortKeys, setSortKeys] = useState(false);
  const [copied, setCopied] = useState(false);

  useEffect(() => {
    document.title = "JSON Prettifier — Xuan Cao";
  }, []);

  const result = useMemo(() => {
    try {
      const parsed = JSON.parse(input);
      const normalized = sortKeys ? sortObjectKeys(parsed) : parsed;
      const pretty = JSON.stringify(normalized, null, indent);
      const minified = JSON.stringify(normalized);

      return {
        valid: true,
        parsed: normalized,
        pretty,
        minified,
        error: "",
      };
    } catch (error) {
      return {
        valid: false,
        parsed: null,
        pretty: "",
        minified: "",
        error: error.message,
      };
    }
  }, [input, indent, sortKeys]);

  const output = result.valid ? result.pretty : "";
  const stats = result.valid
    ? {
        keys: countNodes(result.parsed),
        inputBytes: byteSize(input),
        outputBytes: byteSize(output),
      }
    : {
        keys: 0,
        inputBytes: byteSize(input),
        outputBytes: 0,
      };

  const applyPretty = () => {
    if (result.valid) {
      setInput(result.pretty);
    }
  };

  const applyMinified = () => {
    if (result.valid) {
      setInput(result.minified);
    }
  };

  const clearInput = () => {
    setInput("");
    setCopied(false);
  };

  const copyOutput = async () => {
    if (!result.valid || !output) return;

    try {
      await navigator.clipboard.writeText(output);
      setCopied(true);
      window.setTimeout(() => setCopied(false), 1600);
    } catch (error) {
      setCopied(false);
    }
  };

  return (
    <div className="json-app">
      <div className="container container--wide">
        <header className="json-app__header fade-in">
          <div>
            <p className="section-label">Interactive tool</p>
            <h1 className="page-title">JSON Prettifier</h1>
            <p className="page-subtitle">
              Paste JSON to validate, format, minify, sort object keys, and
              inspect a clean readable output.
            </p>
          </div>
          <div
            className={`json-app__status ${
              result.valid
                ? "json-app__status--valid"
                : "json-app__status--error"
            }`}
            role="status"
          >
            <strong>{result.valid ? "Valid JSON" : "Invalid JSON"}</strong>
            <span>{result.valid ? "Ready to format" : result.error}</span>
          </div>
        </header>

        <section className="json-app__toolbar fade-in fade-in--delay-1">
          <div className="json-app__segmented" aria-label="Indent size">
            {[2, 4].map((size) => (
              <button
                key={size}
                type="button"
                className={indent === size ? "is-active" : ""}
                onClick={() => setIndent(size)}
              >
                {size} spaces
              </button>
            ))}
          </div>

          <label className="json-app__toggle">
            <input
              type="checkbox"
              checked={sortKeys}
              onChange={(event) => setSortKeys(event.target.checked)}
            />
            <span>Sort keys</span>
          </label>

          <div className="json-app__actions">
            <button
              type="button"
              onClick={applyPretty}
              disabled={!result.valid}
            >
              Format
            </button>
            <button
              type="button"
              onClick={applyMinified}
              disabled={!result.valid}
            >
              Minify
            </button>
            <button type="button" onClick={copyOutput} disabled={!result.valid}>
              {copied ? "Copied" : "Copy"}
            </button>
            <button type="button" onClick={clearInput}>
              Clear
            </button>
          </div>
        </section>

        <section className="json-app__workspace fade-in fade-in--delay-2">
          <div className="json-app__panel">
            <div className="json-app__panel-header">
              <h2>Input</h2>
              <p>{stats.inputBytes.toLocaleString()} bytes</p>
            </div>
            <textarea
              value={input}
              onChange={(event) => {
                setInput(event.target.value);
                setCopied(false);
              }}
              spellCheck="false"
              aria-label="JSON input"
            />
          </div>

          <div className="json-app__panel">
            <div className="json-app__panel-header">
              <h2>Output</h2>
              <p>{stats.outputBytes.toLocaleString()} bytes</p>
            </div>
            <pre aria-label="Formatted JSON output">
              {result.valid ? output : result.error}
            </pre>
          </div>
        </section>

        <section className="json-app__metrics fade-in fade-in--delay-3">
          <div>
            <span>Status</span>
            <strong>{result.valid ? "Parsed" : "Needs fix"}</strong>
          </div>
          <div>
            <span>Nodes</span>
            <strong>{stats.keys.toLocaleString()}</strong>
          </div>
          <div>
            <span>Indent</span>
            <strong>{indent} spaces</strong>
          </div>
          <div>
            <span>Key order</span>
            <strong>{sortKeys ? "Sorted" : "Original"}</strong>
          </div>
        </section>
      </div>
    </div>
  );
}

export default JsonPrettifier;
