import React, { useState, useEffect, useCallback } from "react";
import { useParams, useSearchParams, Link } from "react-router-dom";
import ReactMarkdown from "react-markdown";
import remarkGfm from "remark-gfm";
import rehypeRaw from "rehype-raw";
import "./BlogPost.css";

/**
 * Convert a hex string to a Uint8Array.
 */
function hexToBytes(hex) {
  const bytes = new Uint8Array(hex.length / 2);
  for (let i = 0; i < hex.length; i += 2) {
    bytes[i / 2] = parseInt(hex.substring(i, i + 2), 16);
  }
  return bytes;
}

/**
 * Decrypt AES-256-GCM encrypted content using Web Crypto API.
 * Must match the PBKDF2 + AES-GCM params used in fetch.js.
 */
async function decryptBody(encData, password) {
  const salt = hexToBytes(encData.salt);
  const iv = hexToBytes(encData.iv);
  const ciphertextWithTag = hexToBytes(encData.ciphertext);

  // Import password as key material for PBKDF2
  const keyMaterial = await window.crypto.subtle.importKey(
    "raw",
    new TextEncoder().encode(password),
    "PBKDF2",
    false,
    ["deriveKey"]
  );

  // Derive AES-256 key using same params as Node.js
  const key = await window.crypto.subtle.deriveKey(
    {
      name: "PBKDF2",
      salt: salt,
      iterations: 100000,
      hash: "SHA-256",
    },
    keyMaterial,
    { name: "AES-GCM", length: 256 },
    false,
    ["decrypt"]
  );

  // Web Crypto expects ciphertext + authTag concatenated (which is how we stored it)
  const decrypted = await window.crypto.subtle.decrypt(
    { name: "AES-GCM", iv: iv },
    key,
    ciphertextWithTag
  );

  return new TextDecoder().decode(decrypted);
}

function BlogPost() {
  const { slug } = useParams();
  const [searchParams] = useSearchParams();
  const [post, setPost] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(false);
  const [decryptError, setDecryptError] = useState(false);
  const [needsKey, setNeedsKey] = useState(false);
  const [manualKey, setManualKey] = useState("");

  const handleDecrypt = useCallback(async (data, key) => {
    try {
      const decrypted = await decryptBody(data, key);
      const decryptedPost =
        data.payloadType === "private-post"
          ? JSON.parse(decrypted)
          : { ...data, body: decrypted };

      setPost({
        ...decryptedPost,
        encrypted: false,
        secretRoute: data.secretRoute,
      });
      setNeedsKey(false);
      setDecryptError(false);
      document.title = `${decryptedPost.title} — Xuan Cao`;
    } catch (err) {
      console.error("Decryption failed:", err);
      setDecryptError(true);
      setNeedsKey(true);
    }
  }, []);

  useEffect(() => {
    window.scrollTo(0, 0);
    setLoading(true);
    setError(false);
    setPost(null);
    setNeedsKey(false);
    setDecryptError(false);
    const key = searchParams.get("key");

    const loadJsonIfAvailable = async (url) => {
      const response = await fetch(url, {
        headers: { Accept: "application/json" },
      });

      if (!response.ok) {
        return null;
      }

      const contentType = response.headers.get("content-type") || "";
      if (!contentType.includes("application/json")) {
        return null;
      }

      return response.json();
    };

    const loadPost = async () => {
      const publicPost = await loadJsonIfAvailable(
        `${process.env.PUBLIC_URL}/posts/${slug}.json`
      );

      if (publicPost) {
        return publicPost;
      }

      const secretPost = await loadJsonIfAvailable(
        `${process.env.PUBLIC_URL}/secret/posts/${slug}.json`
      );

      if (!secretPost) {
        throw new Error("Post not found");
      }

      return { ...secretPost, secretRoute: true };
    };

    loadPost()
      .then(async (data) => {
        if (data.encrypted) {
          if (key) {
            // Attempt decryption with URL key
            await handleDecrypt(data, key);
          } else {
            // No key provided — prompt for it
            setPost(data);
            setNeedsKey(true);
            document.title = `${data.title} — Encrypted`;
          }
        } else {
          // Normal public post
          setPost(data);
          document.title = `${data.title} — Xuan Cao`;
        }
        setLoading(false);
      })
      .catch((err) => {
        console.error("Failed to load post:", err);
        setError(true);
        setLoading(false);
        document.title = "Post Not Found — Xuan Cao";
      });
  }, [slug, searchParams, handleDecrypt]);

  const backTarget = post?.secretRoute ? "/secret" : "/blog";
  const backLabel = post?.secretRoute ? "← Back to secret" : "← Back";
  const footerBackLabel = post?.secretRoute ? "← Secret posts" : "← All posts";

  const handleManualSubmit = async (e) => {
    e.preventDefault();
    if (!manualKey.trim() || !post) return;
    setDecryptError(false);
    await handleDecrypt(post, manualKey.trim());
  };

  if (loading) {
    return (
      <div className="blog-post">
        <div className="container container--prose">
          <p className="blog-post__loading">Loading…</p>
        </div>
      </div>
    );
  }

  if (error || !post) {
    return (
      <div className="blog-post">
        <div className="container container--prose">
          <p className="blog-post__error">
            Post not found.{" "}
            <Link to="/blog" className="blog-post__back-link">
              ← Back to all posts
            </Link>
          </p>
        </div>
      </div>
    );
  }

  // ── Encrypted post: waiting for key ──────────────────
  if (needsKey) {
    return (
      <div className="blog-post">
        <article className="container container--prose" id={`post-${slug}`}>
          <Link
            to={backTarget}
            className="blog-post__back fade-in"
            id="back-to-blog"
          >
            {backLabel}
          </Link>

          <div className="blog-post__locked fade-in fade-in--delay-1">
            <div className="blog-post__lock-icon">🔒</div>
            <h1 className="blog-post__title">{post.title}</h1>
            <p className="blog-post__lock-message">
              This post is encrypted. Enter the key to read it.
            </p>

            <form
              className="blog-post__key-form"
              onSubmit={handleManualSubmit}
              id="decrypt-form"
            >
              <input
                type="password"
                className="blog-post__key-input"
                placeholder="Enter decryption key"
                value={manualKey}
                onChange={(e) => setManualKey(e.target.value)}
                autoFocus
                id="key-input"
              />
              <button
                type="submit"
                className="blog-post__key-submit"
                id="key-submit"
              >
                Decrypt
              </button>
            </form>

            {decryptError && (
              <p className="blog-post__key-error">
                Incorrect key. Please try again.
              </p>
            )}
          </div>
        </article>
      </div>
    );
  }

  // ── Normal / decrypted post ──────────────────────────
  return (
    <div className="blog-post">
      <article className="container container--prose" id={`post-${slug}`}>
        <Link
          to={backTarget}
          className="blog-post__back fade-in"
          id="back-to-blog"
        >
          {backLabel}
        </Link>

        <header className="blog-post__header fade-in fade-in--delay-1">
          <div className="blog-post__meta">
            <time dateTime={post.date}>
              {new Date(post.date + "T00:00:00").toLocaleDateString("en-US", {
                year: "numeric",
                month: "long",
                day: "numeric",
              })}
            </time>
            {post.readingTime && <span>{post.readingTime}</span>}
          </div>
          <h1 className="blog-post__title">{post.title}</h1>
        </header>

        <div className="blog-post__body prose fade-in fade-in--delay-2">
          <ReactMarkdown
            remarkPlugins={[remarkGfm]}
            rehypePlugins={[rehypeRaw]}
          >
            {post.body}
          </ReactMarkdown>
        </div>

        <footer className="blog-post__footer fade-in fade-in--delay-3">
          {post.tags && post.tags.length > 0 && (
            <div className="blog-post__tags">
              {post.tags.map((tag) => (
                <span key={tag} className="blog-post__tag">
                  {tag}
                </span>
              ))}
            </div>
          )}
          <Link
            to={backTarget}
            className="blog-post__back-link"
            id="post-footer-back"
          >
            {footerBackLabel}
          </Link>
        </footer>
      </article>
    </div>
  );
}

export default BlogPost;
