import React, { useState, useEffect } from "react";
import { Link } from "react-router-dom";
import { profile } from "../../data/profile";
import BlogCard from "../../components/BlogCard/BlogCard";
import "./Home.css";

function Home() {
  const [latestPost, setLatestPost] = useState(null);

  useEffect(() => {
    document.title = `${profile.name} — Portfolio & Blog`;

    fetch(`${process.env.PUBLIC_URL}/posts-manifest.json`)
      .then((res) => res.json())
      .then((posts) => {
        if (posts.length > 0) {
          setLatestPost(posts[0]);
        }
      })
      .catch((err) => console.error("Failed to load posts manifest:", err));
  }, []);

  return (
    <div className="home">
      {/* Hero Section */}
      <section className="home__hero" id="hero-section">
        <div className="container">
          <div className="home__hero-content fade-in">
            <h1 className="home__name">{profile.name}</h1>
            <p className="home__tagline">{profile.tagline}</p>
            <p className="home__bio">{profile.bio}</p>

            <div className="home__links">
              {profile.social.github && (
                <a
                  href={profile.social.github}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="home__link"
                  id="hero-github"
                >
                  GitHub
                </a>
              )}
              {profile.social.linkedin && (
                <a
                  href={profile.social.linkedin}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="home__link"
                  id="hero-linkedin"
                >
                  LinkedIn
                </a>
              )}
              {profile.email && (
                <a
                  href={`mailto:${profile.email}`}
                  className="home__link"
                  id="hero-email"
                >
                  Email
                </a>
              )}
              {profile.resumeUrl && (
                <a
                  href={profile.resumeUrl}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="home__link"
                  id="hero-resume"
                >
                  Resume
                </a>
              )}
            </div>
          </div>
        </div>
      </section>

      {/* Featured Post Section */}
      {latestPost && (
        <section className="home__featured fade-in fade-in--delay-2" id="featured-section">
          <div className="container">
            <hr className="divider" />
            <span className="section-label">Latest Writing</span>
            <BlogCard post={latestPost} featured={true} />
            <Link to="/blog" className="home__all-posts" id="view-all-posts">
              All posts →
            </Link>
          </div>
        </section>
      )}
    </div>
  );
}

export default Home;
