import React, { useMemo, useState } from "react";
import {
  fifa2026Matches,
  fifa2026ScheduleSource,
} from "../../data/fifa2026Schedule";
import { fifaScheduleLocales } from "../../data/fifaScheduleLocalization";
import "./FifaSchedule.css";

const TIME_ZONE_OPTIONS = [
  "America/Toronto",
  "America/New_York",
  "America/Chicago",
  "America/Los_Angeles",
  "America/Mexico_City",
  "America/Vancouver",
  "Europe/London",
  "Europe/Paris",
  "Asia/Tokyo",
  "Australia/Sydney",
];

function getBrowserTimeZone() {
  try {
    const timeZone = Intl.DateTimeFormat().resolvedOptions().timeZone;
    return TIME_ZONE_OPTIONS.includes(timeZone) ? timeZone : "America/Toronto";
  } catch {
    return "America/Toronto";
  }
}

function getDateParts(date, timeZone) {
  const parts = new Intl.DateTimeFormat("en-US", {
    timeZone,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
    hourCycle: "h23",
  }).formatToParts(date);

  return parts.reduce((acc, part) => {
    if (part.type !== "literal") {
      acc[part.type] = Number(part.value);
    }
    return acc;
  }, {});
}

function getTimeZoneOffset(date, timeZone) {
  const parts = getDateParts(date, timeZone);
  return (
    Date.UTC(
      parts.year,
      parts.month - 1,
      parts.day,
      parts.hour,
      parts.minute,
      parts.second
    ) - date.getTime()
  );
}

function venueLocalToUtc(match) {
  const [year, month, day] = match.date.split("-").map(Number);
  const [hour, minute] = match.time.split(":").map(Number);
  const guess = new Date(Date.UTC(year, month - 1, day, hour, minute));
  const firstOffset = getTimeZoneOffset(guess, match.timeZone);
  const firstPass = new Date(guess.getTime() - firstOffset);
  const secondOffset = getTimeZoneOffset(firstPass, match.timeZone);

  if (firstOffset === secondOffset) {
    return firstPass;
  }

  return new Date(guess.getTime() - secondOffset);
}

function formatInTimeZone(date, timeZone, options, locale = "en-US") {
  return new Intl.DateTimeFormat(locale, {
    timeZone,
    ...options,
  }).format(date);
}

function formatDateKey(date, timeZone) {
  const parts = getDateParts(date, timeZone);
  return [
    parts.year,
    String(parts.month).padStart(2, "0"),
    String(parts.day).padStart(2, "0"),
  ].join("-");
}

function addDays(dateKey, days) {
  const [year, month, day] = dateKey.split("-").map(Number);
  const date = new Date(Date.UTC(year, month - 1, day + days));
  return date.toISOString().slice(0, 10);
}

function readableDate(dateKey, timeZone, locale) {
  const [year, month, day] = dateKey.split("-").map(Number);
  const noonUtc = new Date(Date.UTC(year, month - 1, day, 12));
  return formatInTimeZone(
    noonUtc,
    timeZone,
    {
      weekday: "long",
      month: "short",
      day: "numeric",
      year: "numeric",
    },
    locale
  );
}

function formatTime(date, timeZone, locale) {
  return formatInTimeZone(
    date,
    timeZone,
    {
      hour: "numeric",
      minute: "2-digit",
      timeZoneName: "short",
    },
    locale
  );
}

function formatVenueTime(match) {
  return `${match.time} ${match.timeZone.replace(/_/g, " ")}`;
}

function formatMessage(template, values) {
  return Object.entries(values).reduce(
    (message, [key, value]) => message.replace(`{${key}}`, value),
    template
  );
}

function localizeStage(stage, locale) {
  return locale.stages[stage] || stage;
}

function localizeGroup(group, locale) {
  const match = group && group.match(/^Group ([A-L])$/);
  return match ? formatMessage(locale.groupFormat, { group: match[1] }) : group;
}

function localizeParticipant(name, locale) {
  if (!name) {
    return "";
  }

  if (locale.teams[name]) {
    return locale.teams[name];
  }

  const groupStanding = name.match(/^Group ([A-L]) (winners|runners-up)$/);
  if (groupStanding) {
    return `${formatMessage(locale.groupFormat, {
      group: groupStanding[1],
    })} ${locale.groupTerms[groupStanding[2]]}`;
  }

  const thirdPlace = name.match(/^Group ([A-L/]+) third place$/);
  if (thirdPlace) {
    return formatMessage(locale.groupThirdPlace, { groups: thirdPlace[1] });
  }

  const winnerMatch = name.match(/^Winner Match (\d+)$/);
  if (winnerMatch) {
    return formatMessage(locale.winnerMatch, { match: winnerMatch[1] });
  }

  const loserMatch = name.match(/^Loser Match (\d+)$/);
  if (loserMatch) {
    return formatMessage(locale.loserMatch, { match: loserMatch[1] });
  }

  return name;
}

function hasScore(match) {
  return Number.isInteger(match.homeScore) && Number.isInteger(match.awayScore);
}

function formatScore(match, locale) {
  if (!hasScore(match)) {
    return "";
  }

  const score = `${match.homeScore}-${match.awayScore}`;

  if (
    Number.isInteger(match.homePenalties) &&
    Number.isInteger(match.awayPenalties)
  ) {
    return formatMessage(locale.penaltyScoreFormat, {
      awayPenalties: match.awayPenalties,
      homePenalties: match.homePenalties,
      score,
    });
  }

  return match.extraTime
    ? formatMessage(locale.extraTimeScoreFormat, { score })
    : score;
}

function formatMatchTitle(match, locale) {
  const home = localizeParticipant(match.home, locale);
  const away = localizeParticipant(match.away, locale);
  const score = formatScore(match, locale);

  return score
    ? `${home} ${score} ${away}`
    : `${home} ${locale.fixtureSeparator} ${away}`;
}

const BRACKET_CARD_WIDTH = 104;
const BRACKET_CARD_HEIGHT = 70;
const BRACKET_COLUMN_GAP = 8;
const BRACKET_LABEL_HEIGHT = 34;
const BRACKET_ROW_STEP = 78;
const BRACKET_BASE_SLOTS = 8;
const BRACKET_THIRD_PLACE_GAP = 16;

function localizeBracketParticipant(name, locale) {
  if (!name) {
    return "";
  }

  if (/^(Winner|Loser) Match \d+$/.test(name)) {
    return locale.scorePending;
  }

  return localizeParticipant(name, locale);
}

function getBracketParticipants(match, locale) {
  return {
    away: localizeBracketParticipant(match.away, locale),
    home: localizeBracketParticipant(match.home, locale),
  };
}

function getSourceMatchNumber(participant, resultType) {
  const match =
    participant &&
    participant.match(new RegExp(`^${resultType} Match (\\d+)$`));
  return match ? Number(match[1]) : null;
}

function getSourceMatches(match, matchByNumber, resultType) {
  if (!match) {
    return [];
  }

  return [match.homeSource || match.home, match.awaySource || match.away]
    .map((participant) => getSourceMatchNumber(participant, resultType))
    .filter(Boolean)
    .map((matchNumber) => matchByNumber.get(matchNumber))
    .filter(Boolean);
}

function buildKnockoutBranch(rootMatch, matchByNumber) {
  const columns = [];
  let currentColumn = rootMatch ? [rootMatch] : [];

  while (currentColumn.length > 0) {
    columns.push(currentColumn);
    currentColumn = currentColumn.flatMap((match) =>
      getSourceMatches(match, matchByNumber, "Winner")
    );
  }

  return columns;
}

function getBracketTop(matchIndex, matchesInColumn) {
  const groupSize = BRACKET_BASE_SLOTS / matchesInColumn;
  const centerSlot = matchIndex * groupSize + (groupSize - 1) / 2;

  return BRACKET_LABEL_HEIGHT + centerSlot * BRACKET_ROW_STEP;
}

function getBracketConnector(sourceNode, targetNode) {
  const sourceCenterY = sourceNode.y + BRACKET_CARD_HEIGHT / 2;
  const targetCenterY = targetNode.y + BRACKET_CARD_HEIGHT / 2;
  const isMovingRight = sourceNode.x < targetNode.x;
  const sourceX = isMovingRight
    ? sourceNode.x + BRACKET_CARD_WIDTH
    : sourceNode.x;
  const targetX = isMovingRight
    ? targetNode.x
    : targetNode.x + BRACKET_CARD_WIDTH;
  const midX = (sourceX + targetX) / 2;

  return `M ${sourceX} ${sourceCenterY} H ${midX} V ${targetCenterY} H ${targetX}`;
}

function buildKnockoutBracket(matches) {
  const matchByNumber = new Map(matches.map((match) => [match.match, match]));
  const finalMatch = matches.find((match) => match.stage === "Final");

  if (!finalMatch) {
    return {
      columns: [],
      connectors: [],
      height: 0,
      nodes: [],
      width: 0,
    };
  }

  const [leftRoot, rightRoot] = getSourceMatches(
    finalMatch,
    matchByNumber,
    "Winner"
  );
  const leftColumns = buildKnockoutBranch(leftRoot, matchByNumber).reverse();
  const rightColumns = buildKnockoutBranch(rightRoot, matchByNumber);
  const finalColumnIndex = leftColumns.length;
  const displayColumns = [...leftColumns, [finalMatch], ...rightColumns].map(
    (columnMatches, columnIndex) => ({
      id: `bracket-column-${columnIndex}`,
      matches: columnMatches,
      stage: columnMatches[0]?.stage || "",
      x: columnIndex * (BRACKET_CARD_WIDTH + BRACKET_COLUMN_GAP),
    })
  );

  const finalX = finalColumnIndex * (BRACKET_CARD_WIDTH + BRACKET_COLUMN_GAP);
  const finalY = getBracketTop(0, 1);
  const nodes = displayColumns.flatMap((column) =>
    column.matches.map((match, matchIndex) => ({
      isFinal: match.match === finalMatch.match,
      isThirdPlace: false,
      match,
      x: column.x,
      y:
        match.match === finalMatch.match
          ? finalY
          : getBracketTop(matchIndex, column.matches.length),
    }))
  );
  const thirdPlaceMatch = matches.find(
    (match) => match.stage === "Third place"
  );

  if (thirdPlaceMatch) {
    nodes.push({
      isFinal: false,
      isThirdPlace: true,
      match: thirdPlaceMatch,
      x: finalX,
      y: finalY + BRACKET_CARD_HEIGHT + BRACKET_THIRD_PLACE_GAP,
    });
  }

  const nodeByMatch = new Map(nodes.map((node) => [node.match.match, node]));
  const connectors = nodes.flatMap((node) => {
    const winnerConnectors = getSourceMatches(
      node.match,
      matchByNumber,
      "Winner"
    )
      .map((sourceMatch) => nodeByMatch.get(sourceMatch.match))
      .filter(Boolean)
      .map((sourceNode) => ({
        d: getBracketConnector(sourceNode, node),
        id: `${sourceNode.match.match}-${node.match.match}`,
        isSecondary: false,
      }));

    if (!node.isThirdPlace) {
      return winnerConnectors;
    }

    const loserConnectors = getSourceMatches(node.match, matchByNumber, "Loser")
      .map((sourceMatch) => nodeByMatch.get(sourceMatch.match))
      .filter(Boolean)
      .map((sourceNode) => ({
        d: getBracketConnector(sourceNode, node),
        id: `${sourceNode.match.match}-${node.match.match}`,
        isSecondary: true,
      }));

    return [...winnerConnectors, ...loserConnectors];
  });

  return {
    columns: displayColumns,
    connectors,
    height:
      BRACKET_LABEL_HEIGHT +
      (BRACKET_BASE_SLOTS - 1) * BRACKET_ROW_STEP +
      BRACKET_CARD_HEIGHT,
    nodes,
    width:
      displayColumns.length * BRACKET_CARD_WIDTH +
      (displayColumns.length - 1) * BRACKET_COLUMN_GAP,
  };
}

function MatchCard({ match, timeZone, locale }) {
  return (
    <article className="fifa-app__match-card">
      <div className="fifa-app__match-kickoff">
        <span>{formatTime(match.utcDate, timeZone, locale.dateLocale)}</span>
        <strong>
          {formatMessage(locale.matchNumber, { match: match.match })}
        </strong>
      </div>
      <div className="fifa-app__match-main">
        <strong>{formatMatchTitle(match, locale)}</strong>
        <span>
          {localizeGroup(match.group, locale) ||
            localizeStage(match.stage, locale)}{" "}
          - {match.venue}, {match.city}
        </span>
      </div>
    </article>
  );
}

function BracketMatchCard({ node, locale }) {
  const match = node.match;
  const participants = getBracketParticipants(match, locale);
  const score = formatScore(match, locale);

  return (
    <article
      className={[
        "fifa-app__bracket-match",
        node.isFinal ? "fifa-app__bracket-match--final" : "",
        node.isThirdPlace ? "fifa-app__bracket-match--third" : "",
      ]
        .filter(Boolean)
        .join(" ")}
      style={{
        height: BRACKET_CARD_HEIGHT,
        left: node.x,
        top: node.y,
        width: BRACKET_CARD_WIDTH,
      }}
    >
      <div className="fifa-app__bracket-fixture">
        <span>{participants.home}</span>
        <span
          className={
            score
              ? "fifa-app__bracket-score"
              : "fifa-app__bracket-versus"
          }
        >
          {score || locale.fixtureSeparator}
        </span>
        <span>{participants.away}</span>
      </div>
    </article>
  );
}

function KnockoutBracket({ bracket, locale }) {
  if (bracket.nodes.length === 0) {
    return null;
  }

  return (
    <section className="fifa-app__panel fifa-app__knockout fade-in fade-in--delay-3">
      <div className="fifa-app__panel-header">
        <div>
          <h2>{locale.knockoutBracket}</h2>
          <p>
            {formatMessage(locale.knockoutBracketSummary, {
              matches: bracket.nodes.length,
            })}
          </p>
        </div>
      </div>

      <div className="fifa-app__bracket-scroll">
        <div
          className="fifa-app__bracket-canvas"
          style={{
            height: bracket.height,
            width: bracket.width,
          }}
        >
          <svg
            aria-hidden="true"
            className="fifa-app__bracket-lines"
            focusable="false"
            viewBox={`0 0 ${bracket.width} ${bracket.height}`}
          >
            {bracket.connectors.map((connector) => (
              <path
                className={
                  connector.isSecondary
                    ? "fifa-app__bracket-line fifa-app__bracket-line--secondary"
                    : "fifa-app__bracket-line"
                }
                d={connector.d}
                key={connector.id}
              />
            ))}
          </svg>

          {bracket.columns.map((column) => (
            <div
              className="fifa-app__bracket-label"
              key={column.id}
              style={{
                left: column.x,
                width: BRACKET_CARD_WIDTH,
              }}
            >
              {localizeStage(column.stage, locale)}
            </div>
          ))}

          {bracket.nodes.map((node) => (
            <BracketMatchCard
              key={node.match.match}
              locale={locale}
              node={node}
            />
          ))}
        </div>
      </div>
    </section>
  );
}

function DayPanel({ label, dateKey, matches, timeZone, locale }) {
  return (
    <section className="fifa-app__panel fifa-app__day-panel">
      <div className="fifa-app__panel-header">
        <div>
          <h2>{label}</h2>
          <p>{readableDate(dateKey, timeZone, locale.dateLocale)}</p>
        </div>
        <span className="fifa-app__count">{matches.length}</span>
      </div>
      <div className="fifa-app__match-list">
        {matches.length > 0 ? (
          matches.map((match) => (
            <MatchCard
              key={match.match}
              match={match}
              timeZone={timeZone}
              locale={locale}
            />
          ))
        ) : (
          <p className="fifa-app__empty">{locale.noMatchesScheduled}</p>
        )}
      </div>
    </section>
  );
}

function FifaSchedule() {
  const [timeZone, setTimeZone] = useState(getBrowserTimeZone);
  const [language, setLanguage] = useState("en");
  const [anchorDate, setAnchorDate] = useState(() =>
    formatDateKey(new Date(), getBrowserTimeZone())
  );
  const [stageFilter, setStageFilter] = useState("All");
  const [query, setQuery] = useState("");
  const locale = fifaScheduleLocales[language];

  const matches = useMemo(
    () =>
      fifa2026Matches
        .map((match) => ({
          ...match,
          utcDate: venueLocalToUtc(match),
        }))
        .sort((a, b) => a.utcDate - b.utcDate),
    []
  );

  const stages = useMemo(
    () => ["All", ...Array.from(new Set(matches.map((match) => match.stage)))],
    [matches]
  );

  const dayBuckets = useMemo(
    () =>
      [
        { label: locale.dayLabels.today, dateKey: anchorDate },
        { label: locale.dayLabels.tomorrow, dateKey: addDays(anchorDate, 1) },
        {
          label: locale.dayLabels.afterTomorrow,
          dateKey: addDays(anchorDate, 2),
        },
      ].map((day) => ({
        ...day,
        matches: matches.filter(
          (match) => formatDateKey(match.utcDate, timeZone) === day.dateKey
        ),
      })),
    [anchorDate, locale, matches, timeZone]
  );

  const filteredMatches = useMemo(() => {
    const normalizedQuery = query.trim().toLowerCase();

    return matches.filter((match) => {
      const matchesStage = stageFilter === "All" || match.stage === stageFilter;
      const searchable = [
        match.home,
        match.away,
        match.group,
        match.stage,
        formatScore(match, locale),
        localizeParticipant(match.home, locale),
        localizeParticipant(match.away, locale),
        localizeGroup(match.group, locale),
        localizeStage(match.stage, locale),
        match.venue,
        match.city,
        match.country,
        localizeParticipant(match.country, locale),
      ]
        .filter(Boolean)
        .join(" ")
        .toLowerCase();

      return matchesStage && searchable.includes(normalizedQuery);
    });
  }, [locale, matches, query, stageFilter]);

  const knockoutBracket = useMemo(
    () => buildKnockoutBracket(matches),
    [matches]
  );

  const nextMatch =
    matches.find((match) => !hasScore(match)) || matches[matches.length - 1];
  const featuredMatchLabel = hasScore(nextMatch)
    ? locale.latestResult
    : locale.nextKickoff;

  return (
    <div className="fifa-app">
      <div className="container container--wide">
        <header className="fifa-app__header fade-in">
          <div>
            <span className="section-label">{locale.sectionLabel}</span>
            <h1 className="page-title">{locale.pageTitle}</h1>
            <p className="page-subtitle">{locale.pageSubtitle}</p>
            <button
              aria-label={locale.buttonAriaLabel}
              aria-pressed={language === "zhHans"}
              className="fifa-app__language-button"
              onClick={() =>
                setLanguage((currentLanguage) =>
                  currentLanguage === "en" ? "zhHans" : "en"
                )
              }
              type="button"
            >
              {locale.buttonLabel}
            </button>
          </div>
          <a
            className="fifa-app__source"
            href={fifa2026ScheduleSource.url}
            rel="noreferrer"
            role="note"
            target="_blank"
          >
            {formatMessage(locale.sourceNote, {
              source: fifa2026ScheduleSource.label,
              updated: fifa2026ScheduleSource.updated,
            })}
          </a>
        </header>

        <section className="fifa-app__workspace fade-in fade-in--delay-1">
          <form className="fifa-app__panel" aria-label={locale.controlsTitle}>
            <div className="fifa-app__panel-header">
              <div>
                <h2>{locale.controlsTitle}</h2>
                <p>{timeZone.replace(/_/g, " ")}</p>
              </div>
            </div>

            <div className="fifa-app__input-grid">
              <label>
                <span>{locale.timezoneLabel}</span>
                <select
                  value={timeZone}
                  onChange={(event) => setTimeZone(event.target.value)}
                >
                  {TIME_ZONE_OPTIONS.map((option) => (
                    <option key={option} value={option}>
                      {option.replace(/_/g, " ")}
                    </option>
                  ))}
                </select>
              </label>
              <label>
                <span>{locale.anchorDateLabel}</span>
                <input
                  type="date"
                  min="2026-06-01"
                  max="2026-07-31"
                  value={anchorDate}
                  onChange={(event) => setAnchorDate(event.target.value)}
                />
              </label>
              <label>
                <span>{locale.stageLabel}</span>
                <select
                  value={stageFilter}
                  onChange={(event) => setStageFilter(event.target.value)}
                >
                  {stages.map((stage) => (
                    <option key={stage} value={stage}>
                      {stage === "All"
                        ? locale.allStages
                        : localizeStage(stage, locale)}
                    </option>
                  ))}
                </select>
              </label>
              <label>
                <span>{locale.searchLabel}</span>
                <input
                  type="search"
                  value={query}
                  placeholder={locale.searchPlaceholder}
                  onChange={(event) => setQuery(event.target.value)}
                />
              </label>
            </div>
          </form>

          <div className="fifa-app__results">
            <section className="fifa-app__panel">
              <div className="fifa-app__panel-header">
                <div>
                  <h2>{featuredMatchLabel}</h2>
                  <p>
                    {formatMessage(locale.matchNumber, {
                      match: nextMatch.match,
                    })}
                  </p>
                </div>
              </div>
              <div className="fifa-app__hero-number">
                {formatTime(nextMatch.utcDate, timeZone, locale.dateLocale)}
                <span>
                  {formatInTimeZone(
                    nextMatch.utcDate,
                    timeZone,
                    {
                      weekday: "long",
                      month: "short",
                      day: "numeric",
                      year: "numeric",
                    },
                    locale.dateLocale
                  )}
                </span>
              </div>
              <div className="fifa-app__featured-match">
                <strong>{formatMatchTitle(nextMatch, locale)}</strong>
                <span>
                  {localizeStage(nextMatch.stage, locale)} - {nextMatch.venue},{" "}
                  {nextMatch.city}
                </span>
              </div>
            </section>
          </div>
        </section>

        <section className="fifa-app__day-grid fade-in fade-in--delay-2">
          {dayBuckets.map((day) => (
            <DayPanel
              key={day.label}
              label={day.label}
              dateKey={day.dateKey}
              matches={day.matches}
              timeZone={timeZone}
              locale={locale}
            />
          ))}
        </section>

        <KnockoutBracket bracket={knockoutBracket} locale={locale} />

        <section className="fifa-app__panel fifa-app__schedule fade-in fade-in--delay-3">
          <div className="fifa-app__panel-header">
            <div>
              <h2>{locale.completeSchedule}</h2>
              <p>
                {formatMessage(locale.scheduleCount, {
                  filtered: filteredMatches.length,
                  total: matches.length,
                })}
              </p>
            </div>
          </div>

          <div className="fifa-app__table-wrap">
            <table className="fifa-app__table">
              <thead>
                <tr>
                  <th>{locale.tableHeaders.match}</th>
                  <th>{locale.tableHeaders.date}</th>
                  <th>{locale.tableHeaders.kickoff}</th>
                  <th>{locale.tableHeaders.fixture}</th>
                  <th>{locale.tableHeaders.score}</th>
                  <th>{locale.tableHeaders.stage}</th>
                  <th>{locale.tableHeaders.venue}</th>
                  <th>{locale.tableHeaders.venueLocal}</th>
                </tr>
              </thead>
              <tbody>
                {filteredMatches.map((match) => (
                  <tr key={match.match}>
                    <td>{match.match}</td>
                    <td>
                      {formatInTimeZone(
                        match.utcDate,
                        timeZone,
                        {
                          month: "short",
                          day: "numeric",
                          year: "numeric",
                        },
                        locale.dateLocale
                      )}
                    </td>
                    <td>
                      {formatTime(match.utcDate, timeZone, locale.dateLocale)}
                    </td>
                    <td>{formatMatchTitle(match, locale)}</td>
                    <td>{formatScore(match, locale) || locale.scorePending}</td>
                    <td>
                      {localizeGroup(match.group, locale) ||
                        localizeStage(match.stage, locale)}
                    </td>
                    <td>
                      {match.venue}, {match.city}
                    </td>
                    <td>{formatVenueTime(match)}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </section>
      </div>
    </div>
  );
}

export default FifaSchedule;
